    static let planningSections: [DirectoryGuideSection] = [
        .init("trusted-person", "person.crop.circle.badge.checkmark", "Визначте представника завчасно", "Vertretung rechtzeitig festlegen",
              "Поки людина може сама приймати рішення, вона може визначити у Vorsorgevollmacht довірену особу та конкретні справи, якими та займатиметься у разі втрати здатності вирішувати. Документ оформлюють у нотаріуса, адвоката або в простих випадках у Erwachsenenschutzverein та реєструють в ÖZVV; чинним він стає після підтвердження відповідного стану й запису в реєстрі. До підпису з’ясуйте повноваження, витрати й кому зберігати копію.",
              "Solange jemand selbst entscheiden kann, lassen sich in einer Vorsorgevollmacht Vertrauensperson und konkrete Angelegenheiten für einen späteren Verlust der Entscheidungsfähigkeit bestimmen. Errichtung bei Notariat, Rechtsanwaltskanzlei oder in einfachen Fällen beim Erwachsenenschutzverein und Eintragung im ÖZVV; wirksam wird sie nach Eintritt und Registrierung des Vorsorgefalls. Vor der Unterschrift Umfang, Kosten und Aufbewahrung einer Kopie klären.", source: proxy),
        .init("treatment-wishes", "cross.case", "Окремо запишіть медичні побажання", "Behandlungswünsche getrennt festhalten",
